=====useResource=====
     1	import { useCallback, useEffect, useRef, useState } from 'react'
     2	
     3	export type Resource<T> =
     4	  | { status: 'idle' }
     5	  | { status: 'loading' }
     6	  | { status: 'ready'; data: T }
     7	  | { status: 'error'; error: unknown }
     8	
     9	/**
    10	 * Loads one read-only resource identified by `key`. A null key means nothing to load. Changing the key or
    11	 * calling `reload` starts a fresh request and abandons the previous one; a stale response never wins
    12	 * because every settled value is tagged with the request token that produced it.
    13	 * `refreshToken` forces a reload without changing the key (the header Refresh button).
    14	 */
    15	export function useResource<T>(key: string | null, load: (signal: AbortSignal) => Promise<T>, refreshToken = 0): { state: Resource<T>; reload: () => void } {
    16	  const [settled, setSettled] = useState<{ token: string; value: Resource<T> } | null>(null)
    17	  const [attempt, setAttempt] = useState(0)
    18	  const loadRef = useRef(load)
    19	  useEffect(() => { loadRef.current = load }, [load])
    20	  const token = key === null ? null : `${key}\u0000${attempt}\u0000${refreshToken}`
    21	
    22	  useEffect(() => {
    23	    if (token === null) return
    24	    const controller = new AbortController()
    25	    loadRef.current(controller.signal).then(
    26	      data => { if (!controller.signal.aborted) setSettled({ token, value: { status: 'ready', data } }) },
    27	      error => { if (!controller.signal.aborted) setSettled({ token, value: { status: 'error', error } }) },
    28	    )
    29	    return () => controller.abort()
    30	  }, [token])
    31	
    32	  const reload = useCallback(() => setAttempt(previous => previous + 1), [])
    33	  const state: Resource<T> = token === null ? { status: 'idle' } : settled?.token === token ? settled.value : { status: 'loading' }
    34	  return { state, reload }
    35	}
=====routes=====
     1	/**
     2	 * Projects routes: `/projects[/<project>[/workflows/<workflow>[/runs/<run>[/nodes/<node>]]]]`.
     3	 *
     4	 * Every ID is an opaque contract identifier: it must match the shared ID pattern and is percent-encoded
     5	 * as one path segment. Anything else is malformed rather than looked up. This domain is read-only and
     6	 * separate from the Pi/Claude skill sources; nothing here names a filesystem path.
     7	 */
     8	
     9	/** Same pattern as the shared projects contract (`contracts/projects/v1.ts`). */
    10	export const PROJECT_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/
    11	
    12	export const PROJECTS_ROUTE = 'projects'
    13	
    14	export type ProjectsRoute =
    15	  | { level: 'projects' }
    16	  | { level: 'project'; projectId: string }
    17	  | { level: 'workflow'; projectId: string; workflowId: string }
    18	  | { level: 'run'; projectId: string; workflowId: string; runId: string; nodeId: string | null }
    19	
    20	export function isContractId(value: string): boolean {
    21	  return PROJECT_ID_PATTERN.test(value)
    22	}
    23	
    24	function encode(segments: string[]): string {
    25	  return `/${segments.map(encodeURIComponent).join('/')}`
    26	}
    27	
    28	export function projectsPathname(): string {
    29	  return `/${PROJECTS_ROUTE}`
    30	}
    31	
    32	export function projectPathname(projectId: string): string {
    33	  return encode([PROJECTS_ROUTE, projectId])
    34	}
    35	
    36	export function workflowPathname(projectId: string, workflowId: string): string {
    37	  return encode([PROJECTS_ROUTE, projectId, 'workflows', workflowId])
    38	}
    39	
    40	export function runPathname(projectId: string, workflowId: string, runId: string, nodeId: string | null = null): string {
    41	  const segments = [PROJECTS_ROUTE, projectId, 'workflows', workflowId, 'runs', runId]
    42	  if (nodeId !== null) segments.push('nodes', nodeId)
    43	  return encode(segments)
    44	}
    45	
    46	export function routeToPathname(route: ProjectsRoute): string {
    47	  switch (route.level) {
    48	    case 'projects': return projectsPathname()
    49	    case 'project': return projectPathname(route.projectId)
    50	    case 'workflow': return workflowPathname(route.projectId, route.workflowId)
    51	    case 'run': return runPathname(route.projectId, route.workflowId, route.runId, route.nodeId)
    52	  }
    53	}
    54	
    55	/** Whether a pathname belongs to the Projects domain at all (decided before any decoding). */
    56	export function isProjectsPathname(pathname: string): boolean {
    57	  const first = pathname.split('/').filter(segment => segment !== '')[0]
    58	  return first === PROJECTS_ROUTE
    59	}
    60	
    61	/**
    62	 * Parses a Projects pathname. Returns null when it is not a Projects pathname or when any segment is
    63	 * malformed (bad encoding, an invalid ID, an unexpected literal or trailing segments).
    64	 */
    65	export function parseProjectsPathname(pathname: string): ProjectsRoute | null {
    66	  const raw = pathname.split('/').filter(segment => segment !== '')
    67	  if (raw[0] !== PROJECTS_ROUTE) return null
    68	  let segments: string[]
    69	  try {
    70	    segments = raw.slice(1).map(decodeURIComponent)
    71	  } catch {
    72	    return null
    73	  }
    74	  if (segments.length === 0) return { level: 'projects' }
    75	  const [projectId, workflowsLiteral, workflowId, runsLiteral, runId, nodesLiteral, nodeId, ...rest] = segments
    76	  if (!isContractId(projectId)) return null
    77	  if (workflowsLiteral === undefined) return { level: 'project', projectId }
    78	  if (workflowsLiteral !== 'workflows' || workflowId === undefined || !isContractId(workflowId)) return null
    79	  if (runsLiteral === undefined) return { level: 'workflow', projectId, workflowId }
    80	  if (runsLiteral !== 'runs' || runId === undefined || !isContractId(runId)) return null
    81	  if (nodesLiteral === undefined) return { level: 'run', projectId, workflowId, runId, nodeId: null }
    82	  if (nodesLiteral !== 'nodes' || nodeId === undefined || !isContractId(nodeId) || rest.length > 0) return null
    83	  return { level: 'run', projectId, workflowId, runId, nodeId }
    84	}
